import pathlib,hashlib,json,subprocess,os
base=pathlib.Path('/workspace/.proofs'); packet=base/'current-namespace-byte-controls88-v2'; output=base/'captured-namespace-byte-controls88-v2';output.mkdir()
env={**os.environ,**json.loads((base/'native-test-env.json').read_text())};queue=json.loads((packet/'queue.json').read_text());source=packet/'cases.tcl';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();assert sha(source)==queue['source_sha256'];rows=[]
for version,key in [('8.4.20','TCL_LSP_TCLSH84'),('8.5.19','TCL_LSP_TCLSH85'),('8.6.18','TCL_LSP_TCLSH86'),('9.0.4','TCL_LSP_TCLSH90'),('9.1.0','TCL_LSP_TCLSH91'),('jim','TCL_LSP_JIMSH')]:
 directory=output/version;directory.mkdir();executable=pathlib.Path(env[key]);assert executable.is_file();v=subprocess.run([str(executable)],input=b'puts [info patchlevel]\n',env=env,capture_output=True,timeout=10);(directory/'version.stdout').write_bytes(v.stdout);(directory/'version.stderr').write_bytes(v.stderr);r=subprocess.run([str(executable),str(source)],env=env,capture_output=True,timeout=30);(directory/'stdout').write_bytes(r.stdout);(directory/'stderr').write_bytes(r.stderr);record={'provider':version,'channel':queue['channel'],'input_sha256':sha(source),'runner_sha256':sha(pathlib.Path(__file__)),'executable':str(executable),'executable_sha256':sha(executable),'command':[str(executable),str(source)],'reported_version':v.stdout.decode('ascii').strip(),'version_exit':v.returncode,'exit':r.returncode,'stdout_sha256':sha(directory/'stdout'),'stderr_sha256':sha(directory/'stderr'),'rows':len(r.stdout.splitlines()),'limits':'ASCII source shell. No counted API, raw NUL, physical cache, options, or arbitrary namespace protocol grant.'};(directory/'receipt.json').write_text(json.dumps(record,indent=2)+'\n');rows.append(record);(output/'receipt.json').write_text(json.dumps(rows,indent=2)+'\n');print(version,'process',r.returncode,'rows',record['rows'],flush=True)
